INSERT INTO dish (
    name, category_id, price, image, description, status,
    create_time, update_time, create_user, update_user
) VALUES (
             #{name}, #{categoryId}, #{price}, #{image}, #{description}, #{status},
             #{createTime}, #{updateTime}, #{createUser}, #{updateUser}
         )

mapper.select:
SELECT d.id, d.name, d.category_id AS categoryId, d.price, d.image, d.description, d.status, d.update_time AS updateTime, c.name AS categoryName FROM dish d LEFT JOIN category c ON d.category_id = c.id
AND d.name LIKE CONCAT('%', #{name}, '%')
AND d.category_id = #{categoryId}
AND d.status = #{status}
ORDER BY d.create_time DESC

SELECT COUNT(1)
FROM dish d


        AND d.name LIKE CONCAT('%', #{name}, '%')


        AND d.category_id = #{categoryId}


        AND d.status = #{status}

SELECT id, name, category_id, price, image, description, status,
       create_time, update_time, create_user, update_user
FROM dish

    AND category_id = #{categoryId}
    AND status = #{status}

ORDER BY create_time DESC

select count(id) from dish

     and status = #{status} 
     and category_id = #{categoryId}
